import{_t as e,it as t,n,rt as r}from"./chunks/framework.CzJE1L4g.js";var i=JSON.parse(`{"title":"更新日志","description":"","frontmatter":{},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md","lastUpdated":1794143602000}`),a={name:`changelog.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="更新日志" tabindex="-1">更新日志 <a class="header-anchor" href="#更新日志" aria-label="Permalink to “更新日志”">​</a></h1><p>本页记录曦寒流程设计器各版本的变更，只收使用者能感知的改动。<code>@xihan-flow/core</code>、<code>@xihan-flow/runtime</code>、<code>@xihan-flow/designer</code> 三个包总是同一个版本号一起发布。</p><h2 id="v1-0-0-2026-11-08" tabindex="-1">v1.0.0（2026-11-08） <a class="header-anchor" href="#v1-0-0-2026-11-08" aria-label="Permalink to “v1.0.0（2026-11-08）”">​</a></h2><p>首个正式版，以原生 Web Components 交付，不绑定前端框架。流程定义是纯 JSON，查看器展示运行状态，设计器可视化编辑，自带 XiHan 工作流引擎的节点预设。需要 XiHan.UI 5.4.0 及以上。</p><ul><li><strong>新增</strong> <code>@xihan-flow/core</code>：流程定义的结构、校验与问题码、可撤销的编辑操作与连线几何；<code>@xihan-flow/core/presets/xihan-workflow</code> 是 XiHan 工作流引擎的节点预设，流程定义与引擎定义能互相转换。纯 TypeScript，不依赖 DOM。</li><li><strong>新增</strong> <code>@xihan-flow/runtime</code>：<code>&lt;xh-flow-viewer&gt;</code> 查看器：按节点类型画出流程，标出运行状态与高亮，缩放、平移与导出图片；界面语言包与 XiHan.UI 内建语言一一对应。</li><li><strong>新增</strong> <code>@xihan-flow/designer</code>：<code>&lt;xh-flow-designer&gt;</code> 可视化设计器：物料拖放、连线与改连、对齐吸附、自动布局、属性面板与问题列表、小地图、撤销重做与本机草稿。节点类型、属性、规则、命令、面板等都能经 <code>extensions</code> 扩展。</li></ul>`,5)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};